insert into public.poruke (id, tekst, knjiga, poglavlje, redoslijed) values
  (8, 'Najveća nesreća nije biti siromašan ili izgubiti imetak. Najveća je nesreća doživjeti odlazak sa ovoga svijeta bez da je taj čovjek ikada osjetio želju da se približi svome Gospodaru! Ima ljudi koji duboku starost dočekaju, ali nikada u svome životu nisu osjetili poticaj da se približe Gospodaru. Razlog tome je što nije tražio od Allaha, nije kucao na vrata Njegove milosti. Zbog svega toga, mi smo u potrebi probuditi ovaj osjećaj i podići svoju ambiciju.', 'na-putu-ka-milosti', 'Buđenje emocija', 1),
  (10, 'Iskrena želja za Allahovim zadovoljstvom će nas rasteretiti bremena šta će ljudi kazati.', 'na-putu-ka-milosti', 'Iskrenost', 2),
  (1, 'Nekada ti Allah odredi da se razočaraš u ljude, projekte, bezvrijedne neke ideje i svoje navike, kako bi uvidio besmislenost vezanja srca za bilo koga ili bilo šta osim za Živog i Vječnog Koji ne umire. Živ si koliko ti srce zna za Živog.', 'probudi-svoje-srce', 'Vjeruj svom Stvoritelju', 3),
  (9, 'Njegovo ime je El-Vedud, Onaj Koji voli i Onaj Koji je voljen, jer jedino Božije svojstvo koje ima povratno značenje i od Njega prema nama i od nas prema Njemu jeste ljubav.', 'na-putu-ka-milosti', 'Buđenje emocija', 4),
  (11, 'Onaj ko stavi dunjaluk ispred Ahireta — izgubit će oboje, a onaj ko Ahiret stavi ispred dunjaluka — dobit će oboje.', 'na-putu-ka-milosti', 'Organizacija vremena', 5),
  (2, 'Nemoj dopustiti da te poraze loši ljudi i njihova okrutna srca. Nemoj dozvoliti da te njihove riječi uvrijede. Ne dopusti da neko od takvih u tvoje srce posadi očaj! Očaj je hrana šejtanova, a ti prokletnika ne želiš hraniti. Ti svoj put znaš, a mnoštvo onih koji drugim putem idu, neće te pokolebati do tvog cilja. To da li će te neko poštovati ili će sa tobom „pomesti pod“, tvoj je izbor. Ako ti ne cijeniš sebe, neće te sigurno ni neko drugi cijeniti. A samo se pred Allahom kičma savija!', 'probudi-svoje-srce', 'Najbolji je čovjek onaj koji koristi drugima', 6),
  (12, 'Bez obzira da li smo probudili svoje ambicije kroz strah, želju za nagradom, ljubav prema Allahu ili kroz druženje sa čestitima, imamo obavezu taj impuls za dobrom čuvati, jačati i odazvati mu se kroz djelo.', 'na-putu-ka-milosti', 'Buđenje ambicija', 7),
  (13, 'Allah čovjeku daje iskušenje ili da ga očisti od grijeha ili da mu podigne stepen vjerovanja.', 'na-putu-ka-milosti', 'Sudbina', 8),
  (6, 'Bolna je istina da kad kucaš na jedna vrata, a ona se ne otvaraju — ta vrata nisu za tebe. Ohrabrujuća je istina da kad ti se zatvore ta jedna vrata — Gospodar ti otvara druga dvoja. Jer samo On je Onaj Koji otvara, El-Fettah!', 'ucvrsti-svoje-srce', 'Vjeruj', 9),
  (14, 'Možda pojedinac nikada neće uspjeti u svom cilju, da bude bolji i da promijeni neku mahanu, ali Gospodar ne traži pobjednika već borca u čijem srcu izgara nastojanje da bude bolji.', 'na-putu-ka-milosti', 'Sudbina', 10),
  (3, 'Dunjaluk će nam na kraju uzeti sve najljepše što imamo, a mi se opet za njega brinemo. A Džennet nam opet daje sve najljepše što možemo poželjeti, a opet se najmanje za njega brinemo. Zato prije nego što legneš, i ujutro kada ustaneš, prouči Poslanikovu dovu: „Allahu moj, nemoj da dunjaluk bude moja najveća briga!“', 'probudi-svoje-srce', 'Prihvati dunjaluk rukama, a ne srcem', 11),
  (15, 'Iskušenje se ne treba prizivati, ali kad se desi — treba ga razumjeti.', 'na-putu-ka-milosti', 'Sudbina', 12),
  (16, 'Samo treba imati zahvalno srce i dobra djela, a sve ostalo u našim životima Plemeniti Allah, prije ili kasnije, poravna na najljepši način.', 'ucvrsti-svoje-srce', 'Vjeruj', 13),
  (17, 'Allah ne pomaže one koji ne urade sve što je u njihovoj mogućnosti.', 'na-putu-ka-milosti', 'Životni oslonac', 14),
  (4, 'Ako nisi spreman sada, u ovom trenutku, bez obzira na sve, kazati: „Ja sam najsretniji čovjek na svijetu“ — to je znak da još uvijek nisi okusio slast imana (vjerovanja) u svom srcu!', 'probudi-svoje-srce', 'Sreća je tvoja u tebi', 15),
  (18, 'Ako ti Allah oduzme nešto što nisi očekivao da ćeš izgubiti — podarit će ti nešto što nisi očekivao da ćeš dobiti. Samo budi zahvalan Allahu uvijek, u svakoj situaciji!', 'ucvrsti-svoje-srce', 'Vjeruj', 16),
  (19, 'Iskrena vjera u Allaha vjernika čuva od očaja, jer zna da puno više ima nego što pomisli da mu nedostaje.', 'na-putu-ka-milosti', 'Životni oslonac', 17),
  (5, 'Podigni glavu, nasmij se, ne gubi nadu, šta te to na dunjaluku može slomiti dok si sa Onim Ko stvori i upravlja dunjalukom?! Kao što pas sluša svog vlasnika, tako i dunjaluk ponizno dolazi pred čovjeka koji se pokori Vlasniku dunjaluka! Kad si sa Allahom, čitav svijet je tvoj!', 'probudi-svoje-srce', 'Podigni svoje ambicije', 18),
  (20, 'Iskušenja će biti dok je čovjek živ. Samo će se forma mijenjati. Ako ne bude ovo — bit će ono. I zato ne treba očekivati da ona prestanu, jer neće. Treba samo kroz iskušenja učiti i jači postajati. Zadržimo li strpljenje, ojačamo li zahvalnost i učvrstimo li svoj karakter — iskušenja će ustvari poklon postati!', 'ucvrsti-svoje-srce', 'Vjeruj', 19),
  (21, 'Uradimo ono malo što je do nas, pa će nam Gospodar ono puno što nije do nas pomoći.', 'na-putu-ka-milosti', 'Životni oslonac', 20),
  (7, 'Oni koji su spoznali i osjetili ljepotu Allahove ljubavi, to su vidjeli većim i od dunjaluka, imetka, porodice, života, samih sebe, pa čak i od same nagrade, vječne džennetske ljepote, jer Uzvišeni u Kur''anu kaže: „Allahovo zadovoljstvo je najveće.“ (Et-Tevba, 72)', 'oni-koje-allah-voli', 'Koraci ka vječnoj ljubavi', 21),
  (22, 'Jedna antistresna poruka svima koji se bore sa dunjalučkim izazovima: „Dunjaluk kod Allaha ne vrijedi ništa, a pripada Njemu. Pa što ti da mu pridaješ značaj, a ni ne pripada tebi?!“', 'probudi-svoje-srce', 'Prihvati dunjaluk rukama, a ne srcem', 22),
  (23, 'Kada nešto istinski želiš, nikada nemoj prestati sa traženjem toga od Allaha. Jer, ili će ti Allah nešto dati kada dođe pravo vrijeme za to, ili će ti to zamijeniti sa nečim boljim. Vjerujmo Allahu!', 'ucvrsti-svoje-srce', 'Vjeruj', 23),
  (24, 'Koliko god teška neka situacija izgledala, obaveza nam je svoj maksimum dati, pa se srcem na Allaha osloniti.', 'na-putu-ka-milosti', 'Životni oslonac', 24),
  (25, 'U svakom vremenu će postojati izazovi s kojima će se suočavati ljudska duša, a odgovor na sve te izazove treba biti Božija riječ, tačnije razmišljanje o Njegovom govoru.', 'oni-koje-allah-voli', 'Početak putovanja — tražiti viši smisao', 25),
  (26, 'Sve dok ne shvatiš da u ovom životu, po Božijem zakonu, neće i ne može doći dan nakon kojeg više nećeš imati problema — bit ćeš u problemu. Taj trenutak je rezervisan za onu prvu stopu u Džennetu. A ovo je dunjaluk. Zato ne tuguj…', 'probudi-svoje-srce', 'Prihvati dunjaluk rukama, a ne srcem', 26),
  (27, 'Nekada Gospodar uspori ili prekine tvoje planove, jer On Uzvišeni zna i vidi da bi ti planovi mogli usporiti ili prekinuti tebe. Uraditi što je do nas, iz grešaka naučiti lekcije i imati povjerenje u Stvoritelja — ključ je zadovoljstva u srcu i osmijeha na licu.', 'ucvrsti-svoje-srce', 'Rasti', 27),
  (28, 'Čovjek je nesavršen i sve što Allah traži od njega je da iznova radi na sebi i da nikada ne bude od onih koji smatraju da su bez mahane. Najvažnija stvar na putu prema Gospodaru jeste da gledamo stanje svoga srca.', 'na-putu-ka-milosti', 'Borba s vlastitim nedostacima', 28),
  (29, 'Bez unutrašnje čistoće, iskrenosti i pokajanja, nemoguće je ostvariti i izvanjsku, fizičku čistoću, čija su posebna simbolika abdest i namaz. Ko želi da ga Allah zavoli, neka pogleda u svoje srce, a potom neka pogleda u svoja djela — pa će znati da li korača ispravnim putem!', 'oni-koje-allah-voli', 'Očistiti se izvana', 29),
  (30, 'Onaj osjećaj da ti „kamen spadne sa srca“ može dati samo Gospodar srca i to tek onda kada ti je životni princip da ti nikome „kamenja po srcu“ ne stavljaš.', 'probudi-svoje-srce', 'Prihvati dunjaluk rukama, a ne srcem', 30),
  (31, 'Neke od stvari koje nas mogu koštati u životu: naš egoizam, pesimizam, loše društvo, stalno slušanje drugih mišljenja, uzdisanje za tuđim blagodatima, pogrešne navike i opterećenost materijalnim kao najvećom brigom. Naša djela i naši izbori odredit će i naš život!', 'ucvrsti-svoje-srce', 'Oslobodi se', 31),
  (32, 'Strah od Uzvišenog Allaha će ukloniti strah od ljudi.', 'na-putu-ka-milosti', 'Dostojanstvo', 32),
  (33, 'Od znakova Allahove ljubavi prema čovjeku jeste da mu On Uzvišeni podari ispravan odnos prema materijalnom, tj. da udalji dunjaluk od njega.', 'oni-koje-allah-voli', 'Završetak putovanja', 33),
  (34, 'Da budeš sretan u životu — uspjet ćeš kada u svakoj sitnici budeš vidio Allahovu dobrotu prema tebi. Sve dok izvan sebe sreću budeš očekivao, šta god da se desi, da postigneš, ostvariš ili dobiješ — dugotrajnu sreću osjetiti nećeš i opet ćeš tražiti nešto novo „da te usreći“. Zato jer sreća nije pitanje onoga što imaš ili nemaš, već je pitanje srca koje: ili jeste ili nije zahvalno Gospodaru svemira.', 'probudi-svoje-srce', 'Sreća je tvoja u tebi', 34),
  (35, 'Prestanite smirivati oluju, već smirite sebe. Oluja će svakako sama proći. Najbolji način da se osvetite nekome za koga mislite da to zaslužuje jeste da uopće više o osveti ne razmišljate. Stvoreni smo da robujemo Gospodaru, a ne ljudima ili svome egu.', 'ucvrsti-svoje-srce', 'Oslobodi se', 35)
